lums.x = lum( MyGet(uv + (vec2(1.0)/uTexSize)*d.xz) );
lums.y = lum( MyGet(uv - (vec2(1.0)/uTexSize)*d.xz) );
lums.z = lum( MyGet(uv + (vec2(1.0)/uTexSize)*d.zy) );
lums.w = lum( MyGet(uv - (vec2(1.0)/uTexSize)*d.zy) );
vec2 grad = vec2(lums.x-lums.y, lums.z-lums.w)*str * 1000.0/grad_rad;
grad = (clamp01(grad*0.5+0.5) * 2.0-1)*1.4;
// sample previous uFrame
ret = texture( sampler_fc_main, uv + grad*(vec2(1.0)/uTexSize) ).xyz;
// darken (decay) over uTime
ret *= 0.95; //or try: ret -= 0.004;
}

